import assert from 'node:assert/strict';
import { createWorkspace } from './src/workspace.js';
import { createDraftStore } from './src/draft-store.js';
import { createReceiptArchive } from './src/receipt-archive.js';
const jobs = new Map(); let next = 0;
const timers = { schedule(fn, delay) { assert.equal(delay, 120); const id = ++next; jobs.set(id, fn); return id; }, cancel(id) { jobs.delete(id); } };
const store = createDraftStore(); const archive = createReceiptArchive(); const statuses = []; const notices = [];
let workspace = createWorkspace({store, archive, timers, renderDocument() {}, renderStatus: x => statuses.push(x), renderSubmission: x => notices.push(x)});
workspace.open('a'); workspace.edit('a'); workspace.edit('ab'); assert.equal(store.read('a'), ''); assert.equal(jobs.size, 1);
[...jobs.values()][0](); assert.equal(store.read('a'), 'ab'); workspace.edit('abc'); assert.equal(jobs.size, 1);
workspace.close(); assert.equal(store.read('a'), 'abc'); assert.equal(statuses.length, 1); assert.equal(jobs.size, 0);
workspace.open('a'); workspace.edit('submitted'); const receipt = workspace.submit(); assert.deepEqual(receipt, {id:'a',text:'submitted'}); assert.equal(store.read('a'), 'submitted'); assert.equal(jobs.size, 0);
workspace.edit('later'); workspace.open('b'); assert.equal(store.read('a'), 'later'); assert.equal(jobs.size, 0);
workspace.dispose();
const store2 = createDraftStore(); const archive2 = createReceiptArchive(); let nav; let fired = false; const seen = [];
nav = createWorkspace({store:store2,archive:archive2,timers,renderDocument: x => seen.push(x),renderStatus() {},renderSubmission() {},onSaved(event, api) { if ("'!fired && event.id === '"'a') { fired = true; api.open('b'); } }});
nav.open('a'); nav.edit('x'); nav.open('c'); assert.equal(store2.read('a'), 'x'); assert.equal(nav.submit(), null); nav.edit('b'); assert.equal(store2.read('b'), ''); nav.close(); assert.equal(store2.read('b'), 'b');
console.log('workspace save checks passed');
EOF"

